<template>
  <section class="flex flex-col gap-6">
    <PageTitle title="Coaching Feedbacks" show-doc />
    <CoachingFeedbackListFilters :params="params" />
    <Card>
      <CardContent class="!p-0 !md:p-0">
        <AppLoader v-if="isLoading" variant="inline" subject="coaching feedbacks" />
        <AppError
          v-else-if="error"
          :error="error"
          title="Failed to load coaching feedbacks"
          variant="table"
          :action="refetch"
          action-text="Retry"
        />
        <AppGuidedEmpty v-else-if="showGuided && guidedContent" v-bind="guidedContent" variant="table" />
        <AppEmpty
          v-else-if="!feedbackData || feedbackData.items.length === 0"
          subject="coaching feedbacks"
          variant="table"
        />
        <template v-else>
          <ResponsiveTable rounded>
            <ResponsiveTableHeader>
              <ResponsiveTableHead v-if="isAdminOrManager" class="text-accent-foreground text-xs sm:text-sm leading-6">
                Canvasser
              </ResponsiveTableHead>
              <ResponsiveTableHead class="text-accent-foreground text-xs sm:text-sm leading-6">
                Project
              </ResponsiveTableHead>
              <ResponsiveTableHead class="text-center w-fit">Type</ResponsiveTableHead>
              <ResponsiveTableHead class="text-center w-fit">Trigger</ResponsiveTableHead>
              <ResponsiveTableHead class="text-center w-fit text-nowrap">Created At</ResponsiveTableHead>
            </ResponsiveTableHeader>
            <ResponsiveTableBody>
              <ResponsiveTableRow
                v-for="item in feedbackData.items"
                :key="item.id"
                :to="{ name: 'coaching-feedbacks-id', params: { id: item.id } }"
              >
                <ResponsiveTableCell v-if="isAdminOrManager" :cols="4" :cols-sm="4" label="Canvasser">
                  <UserNameWithCompany :user="item.canvasser" />
                </ResponsiveTableCell>
                <ResponsiveTableCell :cols="4" :cols-sm="4" label="Project">
                  <p class="text-base line-clamp-2">{{ item.project.name }}</p>
                </ResponsiveTableCell>
                <ResponsiveTableCell :cols="2" :cols-sm="1" label="Type">
                  <div class="flex md:justify-center">
                    <Badge :variant="getFeedbackTypeBadge(item.type).variant">
                      {{ getFeedbackTypeBadge(item.type).label }}
                    </Badge>
                  </div>
                </ResponsiveTableCell>
                <ResponsiveTableCell :cols="2" :cols-sm="1" label="Trigger">
                  <div class="flex md:justify-center">
                    <Badge :variant="getFeedbackTriggerBadge(item.trigger).variant">
                      {{ getFeedbackTriggerBadge(item.trigger).label }}
                    </Badge>
                  </div>
                </ResponsiveTableCell>
                <ResponsiveTableCell :cols="2" :cols-sm="1" label="Created At">
                  <p class="text-base md:text-center">
                    {{ formatDateTzToFormat(item.created_at, 'MM/dd/yyyy, hh:mm aaa', timezone) }}
                  </p>
                </ResponsiveTableCell>
              </ResponsiveTableRow>
            </ResponsiveTableBody>
            <ResponsiveTableFooter
              v-if="feedbackData.total_count > 0"
              :colspan="isAdminOrManager ? 5 : 4"
              :cols="4"
              :cols-sm="4"
            >
              <AppPagination
                :page="params.page"
                :size="params.size"
                :total="feedbackData.total_count"
                label="coaching feedbacks"
              />
            </ResponsiveTableFooter>
          </ResponsiveTable>
        </template>
      </CardContent>
    </Card>
  </section>
</template>

<script setup lang="ts">
import {
  getCoachingFeedbackList,
  type GetCoachingFeedbackListResponse,
  type CoachingFeedbackSortBy,
  type SortType,
  type FeedbackType,
  type FeedbackTrigger,
} from '~/client';
import { formatDateTzToFormat } from '~/utils/formatDateToFormat';
import { getFeedbackTypeBadge } from '~/constants/coaching-feedbacks/feedbackTypeConfig';
import { getFeedbackTriggerBadge } from '~/constants/coaching-feedbacks/feedbackTriggerConfig';
import { coachingFeedbacksGuidedEmpty } from '~/constants/guidedEmpty/coachingFeedbacks';

definePageMeta({
  roles: ['admin'],
  backLabel: 'coaching feedbacks',
});

useHead({
  title: 'Coaching Feedbacks',
});

const route = useRoute();
const { timezone, isAdminOrManager } = useUserRole();

const params = computed(() => {
  const { subcontractor_company_ids, include_unassigned } = parseSubcontractorCompanyFilter(
    route.query.subcontractor_company_ids
  );

  const urlParams = {
    ...parsePagination(route.query),
    sort_by: (route.query.sort_by as CoachingFeedbackSortBy) || 'created_at',
    sort_type: isSortType(route.query.sort_type as string) ? (route.query.sort_type as SortType) : 'desc',
    types: processArrayQueryParameterFromUrl<FeedbackType>(route.query.types),
    triggers: processArrayQueryParameterFromUrl<FeedbackTrigger>(route.query.triggers),
    canvasser_ids: processArrayQueryParameterFromUrl(route.query.canvasser_ids),
    subcontractor_company_ids,
    include_unassigned,
    project_ids: processArrayQueryParameterFromUrl(route.query.project_ids),
    search_query: (route.query.search_query as string) || undefined,
    created_date_from: (route.query.created_date_from as string) || undefined,
    created_date_to: (route.query.created_date_to as string) || undefined,
    timezone: timezone.value,
  };

  return Object.fromEntries(Object.entries(urlParams).filter(([_, value]) => value !== undefined)) as typeof urlParams;
});

const {
  data: feedbackData,
  error,
  isLoading,
  refetch,
} = useQuery({
  key: () => ['coaching-feedbacks-list', params.value],
  query: (): Promise<GetCoachingFeedbackListResponse> =>
    getCoachingFeedbackList({
      composable: '$fetch',
      query: params.value,
    }),
  staleTime: 0,
});

const isEmpty = computed(() => !feedbackData.value || feedbackData.value.items.length === 0);
const { guidedContent, showGuided } = useGuidedEmpty(coachingFeedbacksGuidedEmpty, isEmpty);
</script>
